from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    def host_matches(host, match_value):
        host = (host or "").lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            base_domain = match_value[2:]
            return host != base_domain and host.endswith("." + base_domain)

        return host == match_value

    def rewrite_url(url, rule):
        parsed = urlsplit(url)
        match_type = rule["match_type"]
        match_value = rule["match_value"]
        action = rule["action"]
        action_value = rule.get("action_value")

        # Determine whether this rule matches.
        if match_type == "path_prefix":
            matched = parsed.path.startswith(match_value)

        elif match_type == "host":
            matched = host_matches(parsed.hostname, match_value)

        elif match_type == "query_param":
            query_params = parse_qsl(parsed.query, keep_blank_values=True)
            matched = any(name == match_value for name, _ in query_params)

        else:
            matched = False

        if not matched:
            return None, False

        if action == "block":
            return None, True

        if action == "strip_prefix":
            path = parsed.path
            if path.startswith(action_value):
                path = path[len(action_value):]
            if not path:
                path = "/"

            rewritten = parsed._replace(path=path)
            return urlunsplit(rewritten), True

        if action == "redirect_host":
            # Preserve user information and the original port.
            userinfo = ""
            if "@" in parsed.netloc:
                userinfo = parsed.netloc.rsplit("@", 1)[0] + "@"

            port = ""
            if parsed.port is not None:
                port = f":{parsed.port}"

            new_host = action_value
            if ":" in new_host and not new_host.startswith("["):
                new_host = f"[{new_host}]"

            rewritten = parsed._replace(
                netloc=f"{userinfo}{new_host}{port}"
            )
            return urlunsplit(rewritten), True

        if action == "add_query_param":
            new_query = action_value
            if parsed.query:
                new_query = f"{parsed.query}&{action_value}"

            rewritten = parsed._replace(query=new_query)
            return urlunsplit(rewritten), True

        # For an unsupported action, leave the URL unchanged.
        return url, True

    results = []

    for url in urls:
        rewritten_url = url

        for rule in rules:
            result, matched = rewrite_url(url, rule)
            if matched:
                rewritten_url = result
                break

        results.append(rewritten_url)

    return results
